    nestedTypes: <String>[
      'BigqueryJobCreateDisposition',
      'BigqueryJobWriteDisposition',
      'BigqueryJobQueryPriority',
      'BigqueryJobParameterMode',
      'BigqueryJobLoadSourceFormat',
      'BigqueryJobExtractCompression',
