  CatalogEntry(
    tfType: 'google_ces_app_root_agent_association',
    className: 'GoogleCesAppRootAgentAssociation',
    barrel: 'ces',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_ces_app_root_agent_association`.',
    constructorParams: <String>[
