    tfType: 'google_compute_autoscaler',
    className: 'GoogleComputeAutoscaler',
    barrel: 'compute',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_compute_autoscaler`.',
    constructorParams: <String>[
      'localName',
