    tfType: 'google_compute_forwarding_rule',
    className: 'GoogleComputeForwardingRule',
    barrel: 'compute',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_compute_forwarding_rule`.',
    constructorParams: <String>[
      'localName',
      'name',
      'region',
      'target',
