    tfType: 'google_compute_health_check',
    className: 'GoogleComputeHealthCheck',
    barrel: 'compute',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_compute_health_check`.',
    constructorParams: <String>[
      'localName',
      'name',
      'description',
      'checkIntervalSec',
      'timeoutSec',
      'healthyThreshold',
      'unhealthyThreshold',
      'sourceRegions',
