  CatalogEntry(
    tfType: 'google_dns_managed_zone_iam_member',
    className: 'GoogleDnsManagedZoneIamMember',
    barrel: 'dns',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_dns_managed_zone_iam_member`.',
    constructorParams: <String>[
