  CatalogEntry(
    tfType: 'google_eventarc_trigger',
    className: 'GoogleEventarcTrigger',
    barrel: 'eventarc',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_eventarc_trigger`.',
    constructorParams: <String>[
      'localName',
      'name',
      'location',
      'matchingCriteria',
      'destination',
      'transport',
      'serviceAccount',
      'channel',
      'eventDataContentType',
