    className: 'GoogleFirebaseAppHostingTraffic',
    barrel: 'firebase_app_hosting',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_firebase_app_hosting_traffic`.',
    constructorParams: <String>[
      'localName',
      'backend',
      'location',
      'target',
      'rolloutPolicy',
