    className: 'GoogleFirebaseRemoteConfigRemoteConfig',
    barrel: 'firebase_remote_config',
    kind: CatalogKind.resource,
    summary:
        'Factory wrapper for `google_firebase_remote_config_remote_config`.',
    constructorParams: <String>[
