    className: 'GoogleMonitoringNotificationChannel',
    barrel: 'monitoring',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_monitoring_notification_channel`.',
    constructorParams: <String>[
      'localName',
      'displayName',
      'type',
      'labels',
      'sensitiveLabels',
      'userLabels',
