  CatalogEntry(
    tfType: 'google_netapp_backup',
    className: 'GoogleNetappBackup',
    barrel: 'netapp',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_netapp_backup`.',
    constructorParams: <String>[
