  CatalogEntry(
    tfType: 'google_project_iam_custom_role',
    className: 'GoogleProjectIamCustomRole',
    barrel: 'iam',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_project_iam_custom_role`.',
