  CatalogEntry(
    tfType: 'google_service_account_key',
    className: 'GoogleServiceAccountKey',
    barrel: 'iam',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_service_account_key`.',
    constructorParams: <String>[
      'localName',
      'serviceAccountId',
