      'SqlEdition',
      'SqlActivationPolicy',
      'SqlDiskType',
      'SqlDatabaseInstanceSettings',
      'SqlDatabaseInstanceIpConfiguration',
      'SqlDatabaseInstanceAuthorizedNetwork',
