  CatalogEntry(
    tfType: 'google_storage_notification',
    className: 'GoogleStorageNotification',
    barrel: 'storage',
    kind: CatalogKind.resource,
    summary: 'Factory wrapper for `google_storage_notification`.',
    constructorParams: <String>[
